patch:
diff --git a/Core/ProjectModels.cs b/Core/ProjectModels.cs
--- a/Core/ProjectModels.cs
+++ b/Core/ProjectModels.cs
@@ -45,6 +45,13 @@ public sealed record RigRecord(
     string DataAssetPath,
     DateTimeOffset CreatedUtc);

+public enum AttachmentStatus
+{
+    Current,
+    Stale
+}
+
 public sealed record AttachmentRecord(
     AttachmentId Id,
     ObjectId ParentObjectId,
@@ -52,7 +59,10 @@ public sealed record AttachmentRecord(
     string Socket,
     TransformState LocalTransform,
-    DateTimeOffset CreatedUtc);
+    DateTimeOffset CreatedUtc,
+    RevisionId? ParentMeshRevisionId = null,
+    RevisionId? ChildMeshRevisionId = null,
+    AttachmentStatus Status = AttachmentStatus.Current);
@@ -325,6 +335,18 @@ public sealed class ProjectState
             if (!_objects.ContainsKey(attachment.ParentObjectId) || !_objects.ContainsKey(attachment.ChildObjectId))
                 throw new InvalidDataException($"Attachment {attachment.Id} references a missing object.");
             if (string.IsNullOrWhiteSpace(attachment.Socket))
                 throw new InvalidDataException($"Attachment {attachment.Id} has no socket name.");
+            if (attachment.ParentMeshRevisionId is { } parentRevisionId &&
+                (!_meshRevisions.TryGetValue(parentRevisionId, out var parentRevision) || parentRevision.ObjectId != attachment.ParentObjectId))
+                throw new InvalidDataException($"Attachment {attachment.Id} parent revision is not a revision of its parent object.");
+            if (attachment.ChildMeshRevisionId is { } childRevisionId &&
+                (!_meshRevisions.TryGetValue(childRevisionId, out var childRevision) || childRevision.ObjectId != attachment.ChildObjectId))
+                throw new InvalidDataException($"Attachment {attachment.Id} child revision is not a revision of its child object.");
+            if ((attachment.ParentMeshRevisionId is null) != (attachment.ChildMeshRevisionId is null))
+                throw new InvalidDataException($"Attachment {attachment.Id} must bind both mesh revisions or neither.");
+            if (attachment.Status == AttachmentStatus.Current && attachment.ParentMeshRevisionId is not null &&
+                (_objects[attachment.ParentObjectId].ActiveMeshRevisionId != attachment.ParentMeshRevisionId ||
+                 _objects[attachment.ChildObjectId].ActiveMeshRevisionId != attachment.ChildMeshRevisionId))
+                throw new InvalidDataException($"Attachment {attachment.Id} is marked current but its bound mesh revisions are stale.");
         }
